// m02-10: смешанные ссылки в правиле + серия кадров
ins('m02-10', 'steps2', p('mixed', '**Мини-эксперимент: зачем `$` в правиле.** Правило относится к выделенному диапазону A2:E7, а адрес в формуле читается для его первой ячейки A2 и «едет» по остальным.\n— `=$E2="Не оплачено"` — столбец E закреплён, строка плавает: закрашивается вся строка P03 и P05.\n— `=E2="Не оплачено"` — ссылка едет и по столбцам: ячейка A2 смотрит на E2, B2 — на F2 (пусто). Закрасится только столбец A у строк P03 и P05.\n— `=E$2="Не оплачено"` — строка закреплена: все ячейки смотрят на E2 («Оплачено»), закрашивания нет.\n— `=$E$2="Не оплачено"` — всё смотрит на одну ячейку E2: либо закрашено всё, либо ничего.\nИзмените формулу в «Управление правилами → Изменить правило» и убедитесь сами.'))
addFigs('m02-10', [
  { after: 'steps2', caption: cap(1, 4, 'выбрать «Условное форматирование → Создать правило»'), src: reconScreen({ app: XLA, window: 'Платежи · A2:E7 выделены', tabs: ['Главная', 'Вставка', 'Данные', 'Вид'], activeTab: 0, buttons: ['Условное форматирование', 'Создать правило', 'Управление правилами'], activeButton: 1, callouts: ['На вкладке «Главная».', '«Условное форматирование → Создать правило».'] }) },
  { after: 'steps2', caption: cap(2, 4, 'выбрать тип «Использовать формулу…»'), src: reconScreen({ app: XLA, window: 'Создание правила форматирования', fields: [['Тип правила', 'Использовать формулу для определения форматируемых ячеек']], activeField: 0, callouts: ['Выберите «Использовать формулу для определения форматируемых ячеек».'] }) },
  { after: 'steps2', caption: cap(3, 4, 'ввести формулу правила'), src: reconScreen({ app: XLA, window: 'Создание правила форматирования', fields: [['Тип правила', 'Использовать формулу…'], ['Формула (должна давать ИСТИНА)', '=$E2="Не оплачено"'], ['Формат', 'заливка: светло-красная']], activeField: 1, callouts: ['В поле формулы введите `=$E2="Не оплачено"`, затем «Формат» → заливка → ОК, ОК.'] }) },
  { after: 'steps2', caption: cap(4, 4, 'результат: закрашены строки P03 и P05'), src: reconScreen({ app: XLA, window: 'Платежи · после правила', grid: grid(['A', 'B', 'C', 'D', 'E'], [['P01', 'Альфа', 'Поставщик', '12000', 'Оплачено'], ['P02', 'Бета', 'Аренда', '8000', 'Оплачено'], ['P03', 'Альфа', 'Аренда', '4000', 'Не оплачено'], ['P04', 'Гамма', 'Поставщик', '9000', 'Оплачено'], ['P05', 'Бета', 'Поставщик', '6000', 'Не оплачено']], 2, [2, 4]), callouts: ['Закрашена вся строка там, где в столбце E «Не оплачено»: P03 (строка 4) и P05 (строка 6).'] }) },
])

// m02-11: 20 сочетаний текстом
ins('m02-11', 'table', p('keys', '**Двадцать сочетаний текстом** (Excel для Windows; на Mac в большинстве вместо `Ctrl` — `Cmd`, остальное сверьте в справке Microsoft):\n— `Ctrl+C` / `Ctrl+V` / `Ctrl+X` — копировать / вставить / вырезать\n— `Ctrl+Z` / `Ctrl+Y` — отменить / вернуть\n— `Ctrl+S` — сохранить\n— `Ctrl+A` — выделить всё\n— `Ctrl+Пробел` / `Shift+Пробел` — выделить столбец / строку\n— `Ctrl+Home` — в начало листа\n— `Ctrl+Shift+End` — выделить до последней используемой ячейки\n— `Ctrl+Shift+↓` — выделить до конца столбца с данными\n— `Ctrl+T` — превратить диапазон в таблицу\n— `Ctrl+1` — формат ячеек\n— `Ctrl+Alt+V` — специальная вставка\n— `Ctrl+D` — заполнить вниз\n— `Ctrl+E` — мгновенное заполнение\n— `Ctrl+Shift+L` — включить или выключить фильтр\n— `Alt+=` — сумма\n— `F2` — редактировать ячейку\n— `F4` — переключить `$` в ссылке\n— `Alt+Enter` — перенос строки внутри ячейки\n— `Ctrl+;` — подставить сегодняшнюю дату'))


